css:
.ocean-scene-pro {
  position: relative;
  width: 100%;
  height: 100%;
  background: linear-gradient(to bottom, #1e3a8a, #0c4a6e, #111827);
  overflow: hidden; /* Crucial for the effect to work */
  border-radius: 1vmax;
  border: 3px solid #a8dadc;
  box-shadow: 0 0 3vmax rgba(168, 218, 220, 0.3);
}
.light-caustics {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 0;
  background: radial-gradient(
      ellipse 40% 50% at 20% 40%,
      rgba(255, 255, 255, 0.1),
      transparent
    ),
    radial-gradient(
      ellipse 30% 40% at 80% 70%,
      rgba(255, 255, 255, 0.08),
      transparent
    );
  animation: caustics-flow 20s linear infinite;
}
.sand-floor {
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  height: 8vmax;
  background: #c2b280;
  border-radius: 50% 40% 0 0 / 10vmax 12vmax 0 0;
  z-index: 1;
}
.seaweed {
  position: absolute;
  width: 100%;
  height: 100%;
  bottom: 0;
  z-index: 2;
}
.seaweed__plant {
  position: absolute;
  bottom: 3vmax;
  width: 1vmax;
  background: linear-gradient(to top, #004d40, #00796b);
  border-radius: 0.5vmax;
  transform-origin: bottom center;
  animation: seaweed-sway 10s ease-in-out infinite;
}
.seaweed__plant--1 {
  left: 10%;
  height: 15vmax;
  animation-delay: -2s;
}
.seaweed__plant--2 {
  left: 80%;
  height: 20vmax;
  animation-delay: -5s;
  transform: scaleX(-1);
}
.seaweed__plant--3 {
  left: 45%;
  height: 12vmax;
  animation-delay: -8s;
}

/* --- NEW: Sea Grass Styling --- */
.sea-grass {
  position: absolute;
  width: 100%;
  height: 100%;
  bottom: 0;
  z-index: 3; /* Placed in front of seaweed but behind fish */
}
.grass-blade {
  position: absolute;
  bottom: 0;
  width: 0.6vmax;
  background: linear-gradient(to top, #2d6a4f, #40916c);
  border-radius: 0.5vmax 0.5vmax 0 0;
  transform-origin: bottom center;
  animation: grass-sway 7s ease-in-out infinite;
}
.grass-blade--1 {
  left: 20%;
  height: 6vmax;
  animation-delay: -1s;
}
.grass-blade--2 {
  left: 22%;
  height: 4vmax;
  animation-delay: -2.5s;
  transform: scaleX(-1);
}
.grass-blade--3 {
  left: 25%;
  height: 7vmax;
  animation-delay: -4s;
}
.grass-blade--4 {
  left: 60%;
  height: 5vmax;
  animation-delay: -1.5s;
}
.grass-blade--5 {
  left: 63%;
  height: 8vmax;
  animation-delay: -5s;
}
.grass-blade--6 {
  left: 65%;
  height: 6vmax;
  animation-delay: -3s;
  transform: scaleX(-1);
}
.grass-blade--7 {
  left: 90%;
  height: 4vmax;
  animation-delay: -6s;
}

/* --- NEW: More Bubbles --- */
.bubbles {
  position: absolute;
  width: 100%;
  height: 100%;
  z-index: 5;
}
.bubble {
  position: absolute;
  bottom: -5vmax;
  border: 0.15vmax solid rgba(255, 255, 255, 0.4);
  border-radius: 50%;
  animation: rise 15s linear infinite;
}
.bubble--1 {
  left: 10%;
  width: 1.5vmax;
  height: 1.5vmax;
  animation-duration: 12s;
  animation-delay: -2s;
}
.bubble--2 {
  left: 30%;
  width: 2.5vmax;
  height: 2.5vmax;
  animation-duration: 18s;
  animation-delay: -8s;
}
.bubble--3 {
  left: 55%;
  width: 1vmax;
  height: 1vmax;
  animation-duration: 10s;
  animation-delay: 0s;
}
.bubble--4 {
  left: 80%;
  width: 3vmax;
  height: 3vmax;
  animation-duration: 15s;
  animation-delay: -5s;
}
.bubble--5 {
  left: 90%;
  width: 1.2vmax;
  height: 1.2vmax;
  animation-duration: 11s;
  animation-delay: -10s;
}
.bubble--6 {
  left: 5%;
  width: 2vmax;
  height: 2vmax;
  animation-duration: 16s;
  animation-delay: -4s;
}
.bubble--7 {
  left: 40%;
  width: 1.8vmax;
  height: 1.8vmax;
  animation-duration: 20s;
  animation-delay: -1s;
}
.bubble--8 {
  left: 25%;
  width: 0.8vmax;
  height: 0.8vmax;
  animation-duration: 9s;
  animation-delay: -12s;
}
.bubble--9 {
  left: 70%;
  width: 2.2vmax;
  height: 2.2vmax;
  animation-duration: 14s;
  animation-delay: -7s;
}
.bubble--10 {
  left: 95%;
  width: 1.5vmax;
  height: 1.5vmax;
  animation-duration: 13s;
  animation-delay: -14s;
}

/* --- SVG Fish Styling --- */
.fish {
  position: absolute;
  z-index: 10;
  filter: drop-shadow(0 0.2vmax 0.5vmax rgba(0, 0, 0, 0.3));
}
.fish--svg {
  width: 12vmax;
  height: 12vmax;
}
.fish--1 {
  animation: swim-path-1 20s linear infinite -2s;
}
.fish--2 {
  filter: hue-rotate(160deg) drop-shadow(0 0.2vmax 0.5vmax rgba(0, 0, 0, 0.3));
  transform: scale(0.8);
  animation: swim-path-2 25s linear infinite -10s;
}
.fish-tail {
  transform-origin: 98px 258px;
  animation: wag-tail-svg 0.8s ease-in-out infinite;
}

/* --- @keyframes Definitions --- */
@keyframes caustics-flow {
  0%,
  100% {
    transform: translate(0, 0) scale(1.1);
  }
  50% {
    transform: translate(2vmax, 5vmax) scale(1);
  }
}
@keyframes seaweed-sway {
  0%,
  100% {
    transform: rotate(5deg);
  }
  50% {
    transform: rotate(-5deg);
  }
}
@keyframes grass-sway {
  0%,
  100% {
    transform: rotate(8deg);
  }
  50% {
    transform: rotate(-8deg);
  }
}
@keyframes rise {
  0% {
    transform: translateY(0) translateX(0);
    opacity: 1;
  }
  50% {
    transform: translateX(2vmax);
  }
  100% {
    transform: translateY(-60vmax) translateX(-2vmax);
    opacity: 0;
  }
}
@keyframes wag-tail-svg {
  0%,
  100% {
    transform: rotate(15deg) skewX(10deg);
  }
  50% {
    transform: rotate(-15deg) skewX(-10deg);
  }
}
@keyframes swim-path-1 {
  0% {
    transform: translate(-20vmax, 10vmax) rotateY(0deg);
  }
  49% {
    transform: translate(60vmax, 15vmax) rotateY(0deg);
  }
  50% {
    transform: translate(60vmax, 15vmax) rotateY(180deg);
  }
  99% {
    transform: translate(-20vmax, 10vmax) rotateY(180deg);
  }
  100% {
    transform: translate(-20vmax, 10vmax) rotateY(180deg);
  }
}
@keyframes swim-path-2 {
  0% {
    transform: translate(60vmax, 45vmax) rotateY(180deg) scale(0.8);
  }
  49% {
    transform: translate(-20vmax, 40vmax) rotateY(180deg) scale(0.8);
  }
  50% {
    transform: translate(-20vmax, 40vmax) rotateY(0deg) scale(0.8);
  }
  99% {
    transform: translate(60vmax, 45vmax) rotateY(0deg) scale(0.8);
  }
  100% {
    transform: translate(60vmax, 45vmax) rotateY(0deg) scale(0.8);
  }
}
